    def parse_one_edit(self, text):
        """
        Parse a single edit block from the LLM response.

        Args:
            text (str): The raw text from the LLM response.

        Returns:
            dict: A dictionary representing the edit (e.g., {'file': 'path/to/file.py', 'lines': [('old', 'new')]}).

        Raises:
            ValueError: If the text cannot be parsed as a code edit.
        """
        try:
            # Try to parse as a code block (e.g., using ast.literal_eval or similar).
            # This is a simplified placeholder; actual implementation may vary.
            lines = text.strip().split('\n')
            if not lines:
                raise ValueError(f"Could not parse following text as code edit: \n{text}")

            # Check if the first line is a file path (e.g., 'path/to/file.py').
            if lines[0].strip().endswith('.py') or lines[0].strip().endswith('.js') or lines[0].strip().endswith('.txt'):
                file_path = lines[0].strip()
                edits = []
                for line in lines[1:]:
                    if '=' in line and not line.startswith('#'):  # Skip comments and non-assignments
                        try:
                            key, value = line.split('=', 1)
                            edits.append((key.strip(), value.strip()))
                        except ValueError:
                            continue
                return {
                    'file': file_path,
                    'lines': edits
                }
            else:
                raise ValueError(f"Could not parse following text as code edit: \n{text}")
        except Exception as e:
            raise ValueError(f"Could not parse following text as code edit: \n{text}")

    def parse_all_edits(self, llm_response):
